document.querySelectorAll("[data-review-track]").forEach(o=>{const e=o,t=e.closest(".review-carousel"),a=t?.querySelector("[data-review-prev]"),n=t?.querySelector("[data-review-next]"),r=l=>{const c=e.querySelector(".review-card"),s=c?c.getBoundingClientRect().width+20:300;e.scrollBy({left:l*s,behavior:"smooth"})};a?.addEventListener("click",()=>r(-1)),n?.addEventListener("click",()=>r(1))});
